// =====================================================
// CONSOLIDAR PROGRAMAS TECNICOS (Tech + AyB)
// Lee: Lista Definitiva, Cohortes, Graduadx, Retiradx, Estipendios
// Une por creamos_id - sin almacenar PII
// =====================================================

const norm = (s) => (s || '').toLowerCase().normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9]/g, '_')
  .replace(/_+/g, '_').replace(/^_|_$/g, '');

// Convierte valueRange de Sheets API a array de objetos usando primera fila como headers
const parseSheet = (valueRange) => {
  const rows = (valueRange && valueRange.values) ? valueRange.values : [];
  if (rows.length < 2) return [];
  const headers = rows[0].map(h => norm(h));
  return rows.slice(1).map(row => {
    const obj = {};
    headers.forEach((h, i) => { if (h) obj[h] = (row[i] !== undefined ? String(row[i]) : ''); });
    return obj;
  }).filter(r => r.creamos_id && r.creamos_id.trim() !== '');
};

const techResponse = $('Descargar Tech Sheets').first().json;
const aybResponse  = $('Descargar AyB Sheets').first().json;

const techRanges = techResponse.valueRanges || [];
const aybRanges  = aybResponse.valueRanges  || [];

// Orden de pestanas pedidas: Lista Definitiva, Cohortes, Graduadx, Retiradx, Estipendios
const TABS = ['Lista_Definitiva', 'Cohortes', 'Graduadx', 'Retiradx', 'Estipendios'];

const datos = {}; // mapa creamos_id -> datos del programa tecnico

const procesarRanges = (ranges, programa) => {
  ranges.forEach((vr, i) => {
    const tabName = TABS[i] || 'Otro';
    const rows = parseSheet(vr);

    rows.forEach(r => {
      const cid = r.creamos_id.trim();
      if (!datos[cid]) {
        datos[cid] = {
          Programa_Tecnico:      '',
          Cohorte:               '',
          Estado_Cohorte:        '',
          Fecha_Inicio_Cohorte:  '',
          Fecha_Fin_Cohorte:     '',
          Estipendios_Recibidos: 0,
          En_Lista_Definitiva:   'No',
          En_Cohortes:           'No',
          En_Graduadx:           'No',
          En_Retiradx:           'No',
          En_Estipendios:        'No',
          _programas:            []
        };
      }
      const d = datos[cid];

      if (tabName === 'Lista_Definitiva') {
        d.En_Lista_Definitiva = 'Si';
        if (!d.Programa_Tecnico) d.Programa_Tecnico = programa;
        // Intentar capturar estado y cohorte con nombres flexibles
        const estado = r.estado || r.status || r.situacion || r.condicion || '';
        if (estado && !d.Estado_Cohorte) d.Estado_Cohorte = estado;
        const cohorte = r.cohorte || r.nombre_cohorte || r.cohort || r.grupo || '';
        if (cohorte && !d.Cohorte) d.Cohorte = cohorte;

      } else if (tabName === 'Cohortes') {
        d.En_Cohortes = 'Si';
        if (!d.Programa_Tecnico) d.Programa_Tecnico = programa;
        const cohorte = r.cohorte || r.nombre_cohorte || r.cohort || r.nombre || r.grupo || '';
        if (cohorte) d.Cohorte = cohorte;
        const fi = r.fecha_inicio || r.inicio || r.fecha_inicio_cohorte || '';
        const ff = r.fecha_fin    || r.fin    || r.fecha_fin_cohorte    || '';
        if (fi) d.Fecha_Inicio_Cohorte = fi;
        if (ff) d.Fecha_Fin_Cohorte    = ff;

      } else if (tabName === 'Graduadx') {
        d.En_Graduadx  = 'Si';
        d.Estado_Cohorte = 'Graduadx';
        if (!d.Programa_Tecnico) d.Programa_Tecnico = programa;

      } else if (tabName === 'Retiradx') {
        d.En_Retiradx = 'Si';
        if (d.Estado_Cohorte !== 'Graduadx') d.Estado_Cohorte = 'Retiradx';
        if (!d.Programa_Tecnico) d.Programa_Tecnico = programa;

      } else if (tabName === 'Estipendios') {
        d.En_Estipendios = 'Si';
        d.Estipendios_Recibidos = (d.Estipendios_Recibidos || 0) + 1;
        if (!d.Programa_Tecnico) d.Programa_Tecnico = programa;
      }

      if (!d._programas.includes(programa)) d._programas.push(programa);
    });
  });
};

procesarRanges(techRanges, 'Formacion_Tech');
procesarRanges(aybRanges,  'Formacion_AyB');

// Limpiar y fijar estado final
Object.values(datos).forEach(d => {
  if (d._programas.length > 1) d.Programa_Tecnico = d._programas.join(', ');
  delete d._programas;
  if (!d.Estado_Cohorte) d.Estado_Cohorte = 'Activx';
});

return [{ json: { datos, total: Object.keys(datos).length } }];
